mapper.select:
SELECT id, team_id, user_id, role, status, created_at, updated_at
FROM public.team_members
WHERE team_id = #{teamId}
  AND user_id = #{userId}
  AND status = 'ACTIVE'
LIMIT 1

SELECT EXISTS (
    SELECT 1 FROM public.team_members
    WHERE team_id = #{teamId}
      AND user_id = #{userId}
      AND status = 'ACTIVE'
)

mapper.update:
UPDATE public.team_members
SET role       = #{role},
    status     = #{status},
    updated_at = #{updatedAt}
WHERE id = #{id}
